const { clampDelay } = require("/workspace/src/utils.cjs");
const cases = [[0,100],[-5,100],[50,100],[99,100],[100,100],[250,250],[4999,4999],[5000,5000],[5001,5000],[99999,5000],[100.5,100.5],[4999.5,4999.5]];
let ok = true;
for (const [input, expected] of cases) {
  const got = clampDelay(input);
  const pass = got === expected && typeof got === "number";
  if (!pass) ok = false;
  console.log(`${pass ? "PASS" : "FAIL"} clampDelay(${input}) = ${got} (expected ${expected}, type ${typeof got})`);
}
console.log(ok ? "ALL PASS" : "FAILURES");
'

